<script setup lang="ts">
import { computed, ref, watch } from "vue";
import {
  ParseContestReplayImportPreview,
  PostContestReplayContestPreview,
  PostContestReplayContestRebuild,
} from "@/apis/contest.ts";
import { PostProblemParseId } from "@/apis/problem.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import type { ContestReplayImportPreview } from "@/types/contest.ts";
import {
  buildReplayPreviewMatrix,
  buildReplayProblemMap,
  contestProblemLabel,
  describeReplayPreview,
  moveReplayProblemOrder,
  resolvePreviewMapping,
} from "@/views/contest/contest-replay-common.ts";

// 回放比赛「重新上传榜单、重建成绩」弹窗。
//
// 允许：换榜单文件、调整题目顺序、重选列→题目映射。
// 禁止：增删题目（后端 100145 硬拦）——已关联本回放的普通比赛按 problem_id 集合比对题目一致性，
// 增删会让它们翻红；顺序变更没关系，index 与 problem_map 都由重建流程重算。
//
// 交互顺序：先确定题目顺序（决定文件里 A/B/C 列的含义）→ 再上传文件预览 → 确认重建。
// 顺序放在最前面是刻意的：后端按传入的 problems 顺序建立列对齐，先传文件再改顺序会白传一次。

const props = defineProps<{
  visible: boolean;
  contestId: number;
  /** 当前题目 ID 顺序（编辑页表单里的那份） */
  problemIds: number[];
}>();

const emit = defineEmits<{
  (e: "update:visible", value: boolean): void;
  (e: "rebuilt"): void;
}>();

const { globalProperties } = useCurrentInstance();

const order = ref<number[]>([]);
const titleById = ref<Record<number, string>>({});
const titlesLoading = ref(false);

const fileInput = ref<HTMLInputElement | null>(null);
const file = ref<File | null>(null);
const preview = ref<ContestReplayImportPreview | null>(null);
const mapping = ref<Record<number, number>>({});
const previewing = ref(false);
const submitting = ref(false);

const canUpload = computed(() => order.value.length > 0);
const diagnosis = computed(() => (preview.value ? describeReplayPreview(preview.value) : null));
const matrix = computed(() =>
  preview.value ? buildReplayPreviewMatrix(preview.value.participants, preview.value.sourceProblems.length, 6) : { rows: [], total: 0, truncated: false }
);
const problemMap = computed(() => buildReplayProblemMap(mapping.value));

// 重建被阻断的原因（空串表示可提交）
const blockedReason = computed(() => {
  if (!file.value) {
    return "请先选择榜单文件";
  }
  if (!preview.value) {
    return "请先上传并解析文件";
  }
  if (diagnosis.value?.hasFatal) {
    return diagnosis.value.fatalReason;
  }
  if (problemMap.value.length === 0) {
    return "请至少为一个题目列选择本场题目";
  }
  return "";
});

const moveProblem = (index: number, delta: number) => {
  const next = moveReplayProblemOrder(order.value, index, delta);
  if (next.length !== order.value.length) {
    return;
  }
  order.value = next;
  // 顺序变了，列对齐基准就变了：作废旧预览，避免用旧映射提交
  clearPreview();
};

const clearPreview = () => {
  preview.value = null;
  mapping.value = {};
  file.value = null;
};

const loadTitles = async () => {
  if (props.problemIds.length === 0) {
    return;
  }
  titlesLoading.value = true;
  try {
    const res = await PostProblemParseId([...props.problemIds]);
    if (res.code !== 0) {
      return;
    }
    const map: Record<number, string> = {};
    for (const problem of res.data.problems ?? []) {
      if (problem?.id) {
        map[problem.id] = problem.title ?? "";
      }
    }
    titleById.value = map;
  } finally {
    titlesLoading.value = false;
  }
};

watch(
  () => props.visible,
  async (visible) => {
    if (!visible) {
      return;
    }
    order.value = [...props.problemIds];
    clearPreview();
    await loadTitles();
  },
  { immediate: true }
);

const handleFileChange = async (e: Event) => {
  const input = e.target as HTMLInputElement;
  const picked = input.files?.[0];
  try {
    if (!picked) {
      return;
    }
    if (!canUpload.value) {
      ShowTextTipsError(globalProperties, "本场没有题目，无法对齐榜单");
      return;
    }
    file.value = picked;
    previewing.value = true;
    const res = await PostContestReplayContestPreview(order.value, picked);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      preview.value = null;
      return;
    }
    const parsed = ParseContestReplayImportPreview(res.data);
    preview.value = parsed;
    mapping.value = resolvePreviewMapping(parsed.sourceProblems.length, parsed.targetProblems.length, parsed.problemMap);
  } catch (err) {
    console.error("replay rebuild preview failed", err);
    ShowTextTipsError(globalProperties, "榜单解析失败：请检查网络后重试，或换一个文件");
    preview.value = null;
  } finally {
    previewing.value = false;
    if (input) {
      input.value = "";
    }
  }
};

const handleConfirm = async () => {
  if (submitting.value) {
    return;
  }
  const currentPreview = preview.value;
  if (!currentPreview) {
    return;
  }
  if (blockedReason.value) {
    ShowTextTipsError(globalProperties, blockedReason.value);
    return;
  }
  submitting.value = true;
  try {
    const res = await PostContestReplayContestRebuild(
      props.contestId,
      order.value,
      currentPreview.previewId,
      problemMap.value
    );
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "榜单已重建");
    emit("update:visible", false);
    emit("rebuilt");
  } catch (err) {
    console.error("replay rebuild failed", err);
    ShowTextTipsError(globalProperties, "重建失败：请检查网络后重试；若持续失败请刷新页面确认是否已生效");
  } finally {
    submitting.value = false;
  }
};

const handleClose = () => emit("update:visible", false);
</script>

<template>
  <t-dialog
    :visible="visible"
    header="重新上传榜单并重建成绩"
    :confirm-btn="blockedReason ? null : '重建'"
    :confirm-loading="submitting"
    width="min(820px, 94vw)"
    @confirm="handleConfirm"
    @close="handleClose"
    @cancel="handleClose"
  >
    <t-space direction="vertical" size="small" style="width: 100%">
      <t-alert
        theme="warning"
        message="重建会整体替换这场回放的成绩"
        description="题目允许调整顺序但不能增删（已关联本回放的比赛要求题目集合一致）。结束时间保持不变，开始时间会按新榜单时长重算。"
      />

      <div class="rrb-title">1. 题目顺序（决定文件里 A/B/C 列的含义）</div>
      <div v-if="titlesLoading" class="rrb-hint">正在加载题目…</div>
      <div v-else class="rrb-problem-list">
        <div v-for="(problemId, index) in order" :key="problemId" class="rrb-problem-row">
          <span class="rrb-problem-label">{{ contestProblemLabel(index + 1) }}</span>
          <span class="rrb-problem-title">{{ titleById[problemId] || `题目 #${problemId}` }}</span>
          <t-space size="small">
            <t-button size="small" variant="text" :disabled="index === 0" @click="moveProblem(index, -1)">上移</t-button>
            <t-button
              size="small"
              variant="text"
              :disabled="index === order.length - 1"
              @click="moveProblem(index, 1)"
            >
              下移
            </t-button>
          </t-space>
        </div>
      </div>

      <div class="rrb-title">2. 榜单文件</div>
      <t-space size="small" wrap>
        <t-button variant="outline" :loading="previewing" :disabled="!canUpload" @click="fileInput?.click()">
          选择并解析文件
        </t-button>
        <span v-if="file" class="rrb-hint">{{ file.name }}</span>
        <span v-else class="rrb-hint">支持 CSV；规则与新建回放比赛一致</span>
      </t-space>

      <template v-if="preview">
        <t-alert
          v-if="diagnosis?.hasFatal"
          theme="error"
          :message="diagnosis.fatalReason"
        />
        <div v-else class="rrb-hint">
          识别到 {{ preview.participants.length }} 名选手（其中 {{ diagnosis?.scoredPlayers ?? 0 }} 人有成绩）、{{
            preview.sourceProblems.length
          }}
          道题。
        </div>

        <div class="rrb-title">3. 题目映射（榜单题目列 → 本回放比赛题目）</div>
        <div v-for="source in preview.sourceProblems" :key="source.index" class="rrb-map-row">
          <span class="rrb-problem-label">{{ contestProblemLabel(source.index + 1) }}</span>
          <span class="rrb-arrow">→</span>
          <t-select v-model="mapping[source.index]" placeholder="忽略该题" auto-width clearable>
            <t-option
              v-for="target in preview.targetProblems"
              :key="target.index"
              :value="target.index"
              :label="`${contestProblemLabel(target.index)}. ${target.title}`"
            />
          </t-select>
        </div>

        <div v-if="matrix.rows.length" class="rrb-title">成绩预览</div>
        <div v-if="matrix.rows.length" class="rrb-matrix-wrap">
          <table class="rrb-matrix">
            <thead>
              <tr>
                <th>选手</th>
                <th v-for="source in preview.sourceProblems" :key="source.index">
                  {{ contestProblemLabel(source.index + 1) }}
                </th>
              </tr>
            </thead>
            <tbody>
              <tr v-for="(row, rowIdx) in matrix.rows" :key="rowIdx">
                <td>{{ row.label }}</td>
                <td v-for="(cell, cellIdx) in row.cells" :key="cellIdx" class="rrb-cell">{{ cell }}</td>
              </tr>
            </tbody>
          </table>
        </div>
        <div v-if="matrix.truncated" class="rrb-hint">共 {{ matrix.total }} 名选手，这里只显示前 {{ matrix.rows.length }} 名。</div>
      </template>

      <div v-if="blockedReason && file" class="rrb-blocked">{{ blockedReason }}</div>
    </t-space>

    <input ref="fileInput" type="file" accept=".csv,text/csv" style="display: none" @change="handleFileChange" />
  </t-dialog>
</template>

